insert into auth.users(id,email,raw_user_meta_data) values('00000000-0000-4000-8000-000000000504','board-entities-4@example.test','{}');
insert into public.organizations(id,name,created_by) values('10000000-0000-4000-8000-000000000501','Native Alpha','00000000-0000-4000-8000-000000000501'),('10000000-0000-4000-8000-000000000502','Native Beta','00000000-0000-4000-8000-000000000504');
insert into public.memberships(organization_id,user_id,role) values('10000000-0000-4000-8000-000000000501','00000000-0000-4000-8000-000000000501','OWNER');
insert into public.memberships(organization_id,user_id,role) values('10000000-0000-4000-8000-000000000501','00000000-0000-4000-8000-000000000502','MEMBER');
