insert into public.board_elements(id,organization_id,board_id,element_type,x,y,width,height,content,created_by,updated_by) values('30000000-0000-4000-8000-000000000501','10000000-0000-4000-8000-000000000501','20000000-0000-4000-8000-000000000501','STICKY',0,0,200,160,'{"text":"Reviewed concept"}','00000000-0000-4000-8000-000000000501','00000000-0000-4000-8000-000000000501');
set local role authenticated;
select lives_ok($$select public.set_organization_plugin_enabled('10000000-0000-4000-8000-000000000501','marketing',true)$$,'enable trusted Marketing');
select lives_ok($$select public.prepare_board_entity_conversion('40000000-0000-4000-8000-000000000501','20000000-0000-4000-8000-000000000501','core.task','{"title":"Reviewed task","description":"Explicit Board selection","priority":"HIGH","assigneeId":"00000000-0000-4000-8000-000000000502","scheduledAt":null,"dueAt":null}',array['30000000-0000-4000-8000-000000000501']::uuid[])$$,'prepare durable conversion');
select lives_ok($$select public.prepare_board_entity_conversion('40000000-0000-4000-8000-000000000501','20000000-0000-4000-8000-000000000501','core.task','{"title":"Reviewed task","description":"Explicit Board selection","priority":"HIGH","assigneeId":"00000000-0000-4000-8000-000000000502","scheduledAt":null,"dueAt":null}',array['30000000-0000-4000-8000-000000000501']::uuid[])$$,'identical retry reuses receipt');
select throws_ok($$select public.prepare_board_entity_conversion('40000000-0000-4000-8000-000000000501','20000000-0000-4000-8000-000000000501','core.task','{"title":"Changed task","description":"Explicit Board selection","priority":"HIGH","assigneeId":"00000000-0000-4000-8000-000000000502","scheduledAt":null,"dueAt":null}',array['30000000-0000-4000-8000-000000000501']::uuid[])$$,'PT409',null,'changed preview cannot reuse key');
select set_config('qa.native_target',(select entity_id::text from public.board_entity_conversions where id='40000000-0000-4000-8000-000000000501'),true);
select set_config('qa.native_card',(select card_id::text from public.board_entity_conversions where id='40000000-0000-4000-8000-000000000501'),true);
select lives_ok($$select public.create_task_from_board('40000000-0000-4000-8000-000000000501')$$,'create through Task domain transaction');
select lives_ok($$select public.create_task_from_board('40000000-0000-4000-8000-000000000501')$$,'lost-response retry reuses Task');
select is((select count(*)::int from public.tasks where board_conversion_id='40000000-0000-4000-8000-000000000501'),1,'one canonical Task');
select is((select state from public.board_entity_conversions where id='40000000-0000-4000-8000-000000000501'),'CREATED','receipt commits with Task');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000502',true);
select is((select count(*)::int from public.activity_events where event_type='TASK_CREATED' and entity_id=current_setting('qa.native_target')::uuid),1,'normal Task creation activity fires exactly once');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000501',true);
select throws_ok($$select public.apply_board_operation('20000000-0000-4000-8000-000000000501',jsonb_build_array(jsonb_build_object('id',current_setting('qa.native_card')::uuid,'element_type','ENTITY_CARD','x',300,'y',0,'width',300,'height',180,'rotation',0,'z_index',5,'parent_id',null,'locked',false,'content',jsonb_build_object('reference',jsonb_build_object('entityType','core.task','entityId',current_setting('qa.native_target'),'organizationId','10000000-0000-4000-8000-000000000501'))||'{"title":"stale privileged snapshot"}'::jsonb,'style','{}'::jsonb,'metadata',jsonb_build_object('conversionId','40000000-0000-4000-8000-000000000501'))),array[]::uuid[])$$,'23514',null,'persisted title snapshots rejected');
select throws_ok($$select public.apply_board_operation('20000000-0000-4000-8000-000000000501',jsonb_build_array(jsonb_build_object('id',current_setting('qa.native_card')::uuid,'element_type','ENTITY_CARD','x',300,'y',0,'width',300,'height',180,'rotation',0,'z_index',5,'parent_id',null,'locked',false,'content',jsonb_build_object('reference',jsonb_build_object('entityType','core.task','entityId',current_setting('qa.native_target'),'organizationId','10000000-0000-4000-8000-000000000502')),'style','{}'::jsonb,'metadata',jsonb_build_object('conversionId','40000000-0000-4000-8000-000000000501'))),array[]::uuid[])$$,'23514',null,'foreign organization reference rejected');
select lives_ok($$select public.apply_board_operation('20000000-0000-4000-8000-000000000501',jsonb_build_array(jsonb_build_object('id',current_setting('qa.native_card')::uuid,'element_type','ENTITY_CARD','x',300,'y',0,'width',300,'height',180,'rotation',0,'z_index',5,'parent_id',null,'locked',false,'content',jsonb_build_object('reference',jsonb_build_object('entityType','core.task','entityId',current_setting('qa.native_target'),'organizationId','10000000-0000-4000-8000-000000000501')),'style','{}'::jsonb,'metadata',jsonb_build_object('conversionId','40000000-0000-4000-8000-000000000501'))),array[]::uuid[])$$,'link stable native card');
select lives_ok($$update public.board_elements set archived_at=now() where id=current_setting('qa.native_card')::uuid$$,'archive only the native Board object');
select is((select count(*)::int from public.tasks where board_conversion_id='40000000-0000-4000-8000-000000000501'),1,'native card archive preserves canonical Task');
select lives_ok($$update public.board_elements set archived_at=null where id=current_setting('qa.native_card')::uuid$$,'explicit Board restore retains reference identity');
select lives_ok($$update public.board_elements set x=320,updated_by='00000000-0000-4000-8000-000000000501' where id=current_setting('qa.native_card')::uuid$$,'native geometry persists');
select throws_ok($$update public.board_elements set content=jsonb_set(content,'{reference,entityId}',to_jsonb(gen_random_uuid()::text)) where id=current_setting('qa.native_card')::uuid$$,'23514',null,'reference identity immutable');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000502',true);
select is((select count(*)::int from public.board_entity_conversions),0,'another member cannot read private preview');
select lives_ok($$update public.board_elements set y=30,updated_by='00000000-0000-4000-8000-000000000502' where id=current_setting('qa.native_card')::uuid$$,'another editor can manipulate linked card');
select throws_ok($$select public.create_task_from_board('40000000-0000-4000-8000-000000000501')$$,'42501',null,'another editor cannot replay creator receipt');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000503',true);
select throws_ok($$select public.prepare_board_entity_conversion('40000000-0000-4000-8000-000000000502','20000000-0000-4000-8000-000000000501','core.task','{"title":"Reviewed task","description":"Explicit Board selection","priority":"HIGH","assigneeId":"00000000-0000-4000-8000-000000000502","scheduledAt":null,"dueAt":null}',array['30000000-0000-4000-8000-000000000501']::uuid[])$$,'42501',null,'VIEWER cannot convert');
select throws_ok($$select public.create_task_from_board('40000000-0000-4000-8000-000000000501')$$,'42501',null,'VIEWER cannot replay');
select is((select count(*)::int from public.board_entity_conversions),0,'VIEWER cannot read creation preview');
select is((select count(*)::int from public.board_elements where element_type='ENTITY_CARD'),1,'VIEWER can read reference cards');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000504',true);
select throws_ok($$select public.prepare_board_entity_conversion('40000000-0000-4000-8000-000000000502','20000000-0000-4000-8000-000000000501','core.task','{"title":"Reviewed task","description":"Explicit Board selection","priority":"HIGH","assigneeId":"00000000-0000-4000-8000-000000000502","scheduledAt":null,"dueAt":null}',array['30000000-0000-4000-8000-000000000501']::uuid[])$$,'42501',null,'foreign tenant cannot prepare');
select throws_ok($$select public.create_task_from_board('40000000-0000-4000-8000-000000000501')$$,'42501',null,'foreign tenant cannot replay');
select is((select count(*)::int from public.board_elements),0,'foreign tenant cannot read cards');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000501',true);
select lives_ok($$select public.prepare_board_entity_conversion('40000000-0000-4000-8000-000000000502','20000000-0000-4000-8000-000000000501','marketing.reel-idea','{"title":"Reviewed idea","concept":"Explicit context","hook":null,"contentAngle":null,"callToAction":null,"notes":null,"status":"IDEA","campaignId":null}',array['30000000-0000-4000-8000-000000000501']::uuid[])$$,'prepare marketing.reel-idea');
select lives_ok($$select public.create_marketing_idea_from_board('40000000-0000-4000-8000-000000000502')$$,'create marketing.reel-idea');
select lives_ok($$select public.create_marketing_idea_from_board('40000000-0000-4000-8000-000000000502')$$,'reuse marketing.reel-idea');
select is((select count(*)::int from public.marketing_reel_ideas where board_conversion_id='40000000-0000-4000-8000-000000000502'),1,'single marketing.reel-idea record');
select lives_ok($$select public.prepare_board_entity_conversion('40000000-0000-4000-8000-000000000503','20000000-0000-4000-8000-000000000501','marketing.research-note','{"title":"Reviewed notes","content":"Human research only","category":"OTHER","sourceLabel":null,"sourceUrl":null}',array['30000000-0000-4000-8000-000000000501']::uuid[])$$,'prepare marketing.research-note');
select lives_ok($$select public.create_marketing_note_from_board('40000000-0000-4000-8000-000000000503')$$,'create marketing.research-note');
select lives_ok($$select public.create_marketing_note_from_board('40000000-0000-4000-8000-000000000503')$$,'reuse marketing.research-note');
select is((select count(*)::int from public.marketing_research where board_conversion_id='40000000-0000-4000-8000-000000000503'),1,'single marketing.research-note record');
select lives_ok($$select public.set_organization_plugin_enabled('10000000-0000-4000-8000-000000000501','marketing',false)$$,'disable Marketing');
select throws_ok($$select public.create_marketing_idea_from_board('40000000-0000-4000-8000-000000000502')$$,'42501',null,'disabled plugin blocks replay');
select is((select count(*)::int from public.marketing_reel_ideas),0,'disabled plugin hides records');
select lives_ok($$select public.set_organization_plugin_enabled('10000000-0000-4000-8000-000000000501','marketing',true)$$,'reenable Marketing');
select lives_ok($$select public.create_marketing_idea_from_board('40000000-0000-4000-8000-000000000502')$$,'reenabled plugin recovers same record');
select throws_ok($$update public.board_entity_conversions set state='PREPARED'$$,'42501',null,'client cannot falsify receipt state');
select throws_ok($$delete from public.board_entity_conversions$$,'42501',null,'client cannot delete receipts');
reset role;
delete from public.tasks where board_conversion_id='40000000-0000-4000-8000-000000000501';
set local role authenticated;
select throws_ok($$select public.create_task_from_board('40000000-0000-4000-8000-000000000501')$$,'PT410',null,'deleted created target is never recreated');
reset role;
delete from public.boards where id='20000000-0000-4000-8000-000000000501';
select is((select count(*)::int from public.marketing_reel_ideas where board_conversion_id='40000000-0000-4000-8000-000000000502'),1,'Board deletion preserves canonical item');
select is((select count(*)::int from public.board_entity_conversions where board_id is null),3,'receipt survives Board deletion without dangling Board');
select * from finish();
rollback;
